144	func sessionStartMessage(agentName types.AgentName, emptyRepo bool) string {
145		if agentName == agent.AgentNameCodex {
146			if emptyRepo {
147				return "Entire CLI found no commits yet — checkpoints will activate after your first commit."
148			}
