33	// committedReader provides read access to committed checkpoint data.
34	// Both checkpoint.GitStore (v1) and checkpoint.V2GitStore implement this interface.
35	type committedReader interface {
36		ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*cpkg.CheckpointSummary, error)
