287	// Rewind restores the working directory to a checkpoint.
288	//
289	
290	func (s *ManualCommitStrategy) Rewind(ctx context.Context, w, errW io.Writer, point RewindPoint) error {
291		repo, err := OpenRepository(ctx)
292		if err != nil {
293			return fmt.Errorf("failed to open git repository: %w", err)
294		}
295	
296		// Get the checkpoint commit
297		commitHash := plumbing.NewHash(point.ID)
298		commit, err := repo.CommitObject(commitHash)
299		if err != nil {
300			return fmt.Errorf("failed to get commit: %w", err)
301		}
302	
303		tree, err := commit.Tree()
304		if err != nil {
305			return fmt.Errorf("failed to get tree: %w", err)
306		}
307	
308		// Reset the shadow branch to the rewound checkpoint
309		// This ensures the next checkpoint will only include prompts from this point forward
310		if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
311			// Log warning but don't fail - file restoration is the primary operation
312			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
313		}
314	
315		// Load session state to get untracked files that existed at session start
316		sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
317		var preservedUntrackedFiles map[string]bool
318		if hasSessionTrailer {
319			state, stateErr := s.loadSessionState(ctx, sessionID)
320			if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
321				preservedUntrackedFiles = make(map[string]bool)
322				for _, f := range state.UntrackedFilesAtStart {
323					preservedUntrackedFiles[f] = true
324				}
325			}
326		}
327	
328		// Build set of files in the checkpoint tree (excluding metadata)
329		checkpointFiles := make(map[string]bool)
330		err = tree.Files().ForEach(func(f *object.File) error {
331			if err := ctx.Err(); err != nil {
332				return err //nolint:wrapcheck // Propagating context cancellation
333			}
334			if !strings.HasPrefix(f.Name, entireDir) {
335				checkpointFiles[f.Name] = true
336			}
337			return nil
338		})
339		if err != nil {
340			return fmt.Errorf("failed to list checkpoint files: %w", err)
341		}
342	
343		// Get HEAD tree to identify tracked files
344		head, err := repo.Head()
345		if err != nil {
346			return fmt.Errorf("failed to get HEAD: %w", err)
347		}
348		headCommit, err := repo.CommitObject(head.Hash())
349		if err != nil {
350			return fmt.Errorf("failed to get HEAD commit: %w", err)
351		}
352		headTree, err := headCommit.Tree()
353		if err != nil {
354			return fmt.Errorf("failed to get HEAD tree: %w", err)
355		}
356	
357		// Build set of files tracked in HEAD
358		trackedFiles := make(map[string]bool)
359		//nolint:errcheck // Error is not critical for rewind
360		_ = headTree.Files().ForEach(func(f *object.File) error {
361			if err := ctx.Err(); err != nil {
362				return err //nolint:wrapcheck // Propagating context cancellation
363			}
364			trackedFiles[f.Name] = true
365			return nil
366		})
367	
368		// Get repository root to walk from there
369		repoRoot, err := paths.WorktreeRoot(ctx)
370		if err != nil {
371			repoRoot = "." // Fallback to current directory
372		}
373	
374		// Open os.Root at repo root for traversal-resistant file operations.
375		// Defense-in-depth: paths come from git tree objects (trusted) but we
376		// still scope operations to prevent any escape from the repo root.
377		repoRootHandle, err := os.OpenRoot(repoRoot)
378		if err != nil {
379			return fmt.Errorf("failed to open repo root: %w", err)
380		}
381		defer repoRootHandle.Close()
382	
383		// Find and delete untracked files that aren't in the checkpoint.
384		// Uses git ls-files to only consider non-ignored files, avoiding walks through
385		// large ignored directories like node_modules/.
386		untrackedNow, err := collectUntrackedFiles(ctx)
387		if err != nil {
388			// Non-fatal - continue with restoration
389			fmt.Fprintf(errW, "Warning: error listing untracked files: %v\n", err)
390		}
391		for _, relPath := range untrackedNow {
392			// If file is in checkpoint, it will be restored
393			if checkpointFiles[relPath] {
394				continue
395			}
396	
397			// If file is tracked in HEAD, don't delete (user's committed work)
398			if trackedFiles[relPath] {
399				continue
400			}
401	
402			// If file existed at session start, preserve it (untracked user files)
403			if preservedUntrackedFiles[relPath] {
404				continue
405			}
406	
407			// File is untracked and not in checkpoint - delete it via os.Root
408			if removeErr := osroot.Remove(repoRootHandle, relPath); removeErr == nil {
409				fmt.Fprintf(w, "  Deleted: %s\n", relPath)
410			}
411		}
412	
413		// Restore files from checkpoint
414		err = tree.Files().ForEach(func(f *object.File) error {
415			if err := ctx.Err(); err != nil {
416				return err //nolint:wrapcheck // Propagating context cancellation
417			}
418			// Skip metadata directories - these are for checkpoint storage, not working dir
419			if strings.HasPrefix(f.Name, entireDir) {
420				return nil
421			}
422	
423			contents, err := f.Contents()
424			if err != nil {
425				return fmt.Errorf("failed to read file %s: %w", f.Name, err)
426			}
427	
428			// Ensure directory exists (MkdirAll not available on os.Root)
429			absPath := filepath.Join(repoRoot, f.Name)
430			dir := filepath.Dir(absPath)
431			if dir != "." {
432				//nolint:gosec // G301: Need 0o755 for user directories during rewind
433				if err := os.MkdirAll(dir, 0o755); err != nil {
434					return fmt.Errorf("failed to create directory %s: %w", dir, err)
435				}
436			}
437	
438			// Write file with appropriate permissions via os.Root
439			var perm os.FileMode = 0o644
440			if f.Mode == filemode.Executable {
441				perm = 0o755
442			}
443			if err := osroot.WriteFile(repoRootHandle, f.Name, []byte(contents), perm); err != nil {
444				return fmt.Errorf("failed to write file %s: %w", f.Name, err)
445			}
446	
447			fmt.Fprintf(w, "  Restored: %s\n", f.Name)
448			return nil
449		})
450		if err != nil {
451			return fmt.Errorf("failed to iterate tree files: %w", err)
452		}
453	
454		// Restore agent-contributed files (e.g., Cursor chat archives) to their
455		// native storage locations. Inverse of CheckpointContributor.
456		if hasSessionTrailer {
457			restoreAgentCheckpointFiles(ctx, errW, tree, sessionID)
458		}
459	
460		fmt.Fprintln(w)
461		if len(point.ID) >= 7 {
462			fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID[:7])
463		} else {
464			fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID)
465		}
466		fmt.Fprintln(w)
467	
468		return nil
469	}
470	
471	// restoreAgentCheckpointFiles extracts agent-contributed files from the
472	// checkpoint tree and hands them to the agent's CheckpointRestorer (if any).
473	// Best-effort: errors are logged but do not fail the rewind.
474	func restoreAgentCheckpointFiles(ctx context.Context, errW io.Writer, tree *object.Tree, sessionID string) {
475		ag, err := agentForSession(ctx, sessionID)
476		if err != nil || ag == nil {
477			return
478		}
479		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
480		extras := extractExtraFilesFromTree(tree, metadataDir)
481		runCheckpointRestorer(ctx, errW, ag, sessionID, extras)
482	}
483	
484	// runCheckpointRestorer invokes a CheckpointRestorer if the agent implements it
485	// and there is anything to restore. Errors are non-fatal.
486	func runCheckpointRestorer(ctx context.Context, errW io.Writer, ag agent.Agent, sessionID string, files map[string][]byte) {
487		if len(files) == 0 {
488			return
489		}
490		restorer, ok := ag.(agent.CheckpointRestorer)
491		if !ok {
492			return
493		}
494		if err := restorer.RestoreCheckpointFiles(ctx, sessionID, files); err != nil {
495			fmt.Fprintf(errW, "[entire] Warning: agent checkpoint restore failed: %v\n", err)
496		}
497	}
498	
499	// agentForSession resolves the agent registered for a session by loading its
500	// state and looking up the agent type in the registry. Returns (nil, nil)
501	// when the session has no recorded agent or no state exists.
502	func agentForSession(ctx context.Context, sessionID string) (agent.Agent, error) {
503		state, err := LoadSessionState(ctx, sessionID)
504		if err != nil {
505			return nil, fmt.Errorf("load session state: %w", err)
506		}
507		if state == nil || state.AgentType == "" {
508			return nil, nil //nolint:nilnil // "no agent resolvable" is the happy no-op
509		}
510		return ResolveAgentForRewind(state.AgentType)
511	}
512	
513	// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
514	// This ensures that when the user commits after rewinding, the next checkpoint will only
515	// include prompts from the rewound point, not prompts from later checkpoints.
516	func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
517		// Extract session ID from the checkpoint commit's Entire-Session trailer
518		sessionID, found := trailers.ParseSession(commit.Message)
519		if !found {
520			return errors.New("checkpoint has no Entire-Session trailer")
521		}
522	
523		// Load session state to get the shadow branch name
524		state, err := s.loadSessionState(ctx, sessionID)
525		if err != nil {
526			return fmt.Errorf("failed to load session state: %w", err)
527		}
528		if state == nil {
529			return fmt.Errorf("session %s not found", sessionID)
530		}
531	
532		// Reset the shadow branch to the checkpoint commit
533		shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
534		refName := plumbing.NewBranchReferenceName(shadowBranchName)
535	
536		// Update the reference to point to the checkpoint commit
537		ref := plumbing.NewHashReference(refName, commit.Hash)
538		if err := repo.Storer.SetReference(ref); err != nil {
539			return fmt.Errorf("failed to update shadow branch: %w", err)
540		}
541	
542		fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
543		return nil
544	}
545	
546	// CanRewind checks if rewinding is possible.
547	// For manual-commit strategy, rewind restores files from a checkpoint - uncommitted changes are expected
548	// and will be replaced by the checkpoint contents. Returns true with a warning message showing
549	// what changes will be reverted.
550	func (s *ManualCommitStrategy) CanRewind(ctx context.Context) (bool, string, error) {
551		return checkCanRewindWithWarning(ctx)
552	}
553	
554	// PreviewRewind returns what will happen if rewinding to the given point.
555	// This allows showing warnings about untracked files that will be deleted.
556	func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
557		// Logs-only points don't modify the working directory
558		if point.IsLogsOnly {
559			return &RewindPreview{}, nil
560		}
561	
562		repo, err := OpenRepository(ctx)
563		if err != nil {
564			return nil, fmt.Errorf("failed to open git repository: %w", err)
565		}
566	
567		// Get the checkpoint commit
568		commitHash := plumbing.NewHash(point.ID)
569		commit, err := repo.CommitObject(commitHash)
570		if err != nil {
571			return nil, fmt.Errorf("failed to get commit: %w", err)
572		}
573	
574		tree, err := commit.Tree()
575		if err != nil {
576			return nil, fmt.Errorf("failed to get tree: %w", err)
577		}
578	
579		// Load session state to get untracked files that existed at session start
580		sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
581		var preservedUntrackedFiles map[string]bool
582		if hasSessionTrailer {
583			state, stateErr := s.loadSessionState(ctx, sessionID)
584			if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
585				preservedUntrackedFiles = make(map[string]bool)
586				for _, f := range state.UntrackedFilesAtStart {
587					preservedUntrackedFiles[f] = true
588				}
589			}
590		}
591	
592		// Build set of files in the checkpoint tree (excluding metadata)
593		checkpointFiles := make(map[string]bool)
594		var filesToRestore []string
595		err = tree.Files().ForEach(func(f *object.File) error {
596			if err := ctx.Err(); err != nil {
597				return err //nolint:wrapcheck // Propagating context cancellation
598			}
599			if !strings.HasPrefix(f.Name, entireDir) {
600				checkpointFiles[f.Name] = true
601				filesToRestore = append(filesToRestore, f.Name)
602			}
603			return nil
604		})
605		if err != nil {
606			return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
607		}
608	
609		// Get HEAD tree to identify tracked files
610		head, err := repo.Head()
611		if err != nil {
612			return nil, fmt.Errorf("failed to get HEAD: %w", err)
613		}
614		headCommit, err := repo.CommitObject(head.Hash())
615		if err != nil {
616			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
617		}
618		headTree, err := headCommit.Tree()
619		if err != nil {
620			return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
621		}
622	
623		// Build set of files tracked in HEAD
624		trackedFiles := make(map[string]bool)
625		//nolint:errcheck // Error is not critical for preview
626		_ = headTree.Files().ForEach(func(f *object.File) error {
627			if err := ctx.Err(); err != nil {
628				return err //nolint:wrapcheck // Propagating context cancellation
629			}
630			trackedFiles[f.Name] = true
631			return nil
632		})
633	
634		// Find untracked files that would be deleted.
635		// Uses git ls-files to only consider non-ignored files.
636		var filesToDelete []string
637		untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
638		if untrackedErr != nil {
639			fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
640			return &RewindPreview{
641				FilesToRestore: filesToRestore,
642				FilesToDelete:  filesToDelete,
643			}, nil
644		}
645		for _, relPath := range untrackedNow {
646			if checkpointFiles[relPath] {
647				continue
648			}
649			if trackedFiles[relPath] {
650				continue
651			}
652			if preservedUntrackedFiles[relPath] {
653				continue
654			}
655			filesToDelete = append(filesToDelete, relPath)
656		}
657	
658		// Sort for consistent output
659		sort.Strings(filesToRestore)
660		sort.Strings(filesToDelete)
661	
662		return &RewindPreview{
663			FilesToRestore: filesToRestore,
664			FilesToDelete:  filesToDelete,
665		}, nil
666	}
667	
668	// RestoreLogsOnly restores session logs from a logs-only rewind point.
669	// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
670	// Does not modify the working directory.
671	// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
672	// If force is false, prompts for confirmation when local logs have newer timestamps.
673	// Returns info about each restored session so callers can print correct per-session resume commands.
674	func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, w, errW io.Writer, point RewindPoint, force bool) ([]RestoredSession, error) {
675		if !point.IsLogsOnly {
676			return nil, errors.New("not a logs-only rewind point")
677		}
678	
679		if point.CheckpointID.IsEmpty() {
680			return nil, errors.New("missing checkpoint ID")
681		}
682	
683		// Resolve which store has this checkpoint. Try v2 first when enabled.
684		// The chosen reader is used for all subsequent reads (summary + session content)
685		// to avoid mixed v1/v2 reads. No per-session fallback to v1: during dual-write,
686		// both stores receive the same data, so if v2 has the summary it also has the
687		// transcripts on /full/* refs.
688		var reader committedReader
689		var summary *cpkg.CheckpointSummary
690	
691		if settings.IsCheckpointsV2Enabled(ctx) {
692			v2Store, v2Err := s.getV2CheckpointStore(ctx)
693			if v2Err == nil {
694				v2Summary, readErr := v2Store.ReadCommitted(ctx, point.CheckpointID)
695				if readErr != nil {
696					logging.Debug(ctx, "v2 ReadCommitted failed, falling back to v1",
697						slog.String("checkpoint_id", string(point.CheckpointID)),
698						slog.String("error", readErr.Error()),
699					)
700				} else if v2Summary != nil {
701					reader = v2Store
702					summary = v2Summary
703				}
704			}
705		}
706	
707		if summary == nil {
708			v1Store, err := s.getCheckpointStore()
709			if err != nil {
710				return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
711			}
712			summary, err = v1Store.ReadCommitted(ctx, point.CheckpointID)
713			if err != nil {
714				return nil, fmt.Errorf("failed to read checkpoint: %w", err)
715			}
716			reader = v1Store
717		}
718		if summary == nil {
719			return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
720		}
721	
722		// Get worktree root for agent session directory lookup
723		repoRoot, err := paths.WorktreeRoot(ctx)
724		if err != nil {
725			return nil, fmt.Errorf("failed to get worktree root: %w", err)
726		}
727	
728		// Check for newer local logs if not forcing
729		if !force {
730			sessions := s.classifySessionsForRestore(ctx, repoRoot, reader, point.CheckpointID, summary)
731			hasConflicts := false
732			for _, sess := range sessions {
733				if sess.Status == StatusLocalNewer {
734					hasConflicts = true
735					break
736				}
737			}
738			if hasConflicts {
739				shouldOverwrite, promptErr := PromptOverwriteNewerLogs(errW, sessions)
740				if promptErr != nil {
741					return nil, promptErr
742				}
743				if !shouldOverwrite {
744					fmt.Fprintf(w, "Resume cancelled. Local session logs preserved.\n")
745					return nil, nil
746				}
747			}
748		}
749	
750		// Count sessions to restore
751		totalSessions := len(summary.Sessions)
752		if totalSessions > 1 {
753			fmt.Fprintf(w, "Restoring %d sessions from checkpoint:\n", totalSessions)
754		}
755	
756		// Restore all sessions (oldest to newest, using 0-based indexing)
757		var restored []RestoredSession
758		for i := range totalSessions {
759			content, readErr := reader.ReadSessionContent(ctx, point.CheckpointID, i)
760			if readErr != nil {
761				if !errors.Is(readErr, cpkg.ErrNoTranscript) {
762					fmt.Fprintf(errW, "  Warning: failed to read session %d: %v\n", i, readErr)
763				}
764				continue
765			}
766			if content == nil || len(content.Transcript) == 0 {
767				continue
768			}
769	
770			sessionID := content.Metadata.SessionID
771			if sessionID == "" {
772				fmt.Fprintf(errW, "  Warning: session %d has no session ID, skipping\n", i)
773				continue
774			}
775	
776			// Resolve per-session agent from metadata — skip if agent is unknown
777			if content.Metadata.Agent == "" {
778				fmt.Fprintf(errW, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
779				continue
780			}
781			sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
782			if agErr != nil {
783				fmt.Fprintf(errW, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
784				continue
785			}
786	
787			// Compute transcript path from current repo location for cross-machine portability.
788			sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
789			if dirErr != nil {
790				fmt.Fprintf(errW, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
791				continue
792			}
793			sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
794			if resolver, ok := sessionAgent.(agent.RestoredSessionPathResolver); ok {
795				resolvedFile, resolveErr := resolver.ResolveRestoredSessionFile(sessionAgentDir, sessionID, content.Transcript)
796				if resolveErr != nil {
797					fmt.Fprintf(errW, "  Warning: failed to resolve restored session path for session %d (%s): %v (using fallback path)\n", i, sessionID, resolveErr)
798				} else {
799					sessionFile = resolvedFile
800				}
801			}
802	
803			// Get first prompt for display
804			promptPreview := ExtractFirstPrompt(content.Prompts)
805	
806			if totalSessions > 1 {
807				isLatest := i == totalSessions-1
808				if promptPreview != "" {
809					if isLatest {
810						fmt.Fprintf(w, "  Session %d (latest): %s\n", i+1, promptPreview)
811					} else {
812						fmt.Fprintf(w, "  Session %d: %s\n", i+1, promptPreview)
813					}
814				}
815				fmt.Fprintf(w, "    Writing to: %s\n", sessionFile)
816			} else {
817				fmt.Fprintf(w, "Writing transcript to: %s\n", sessionFile)
818			}
819	
820			// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
821			if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
822				fmt.Fprintf(errW, "    Warning: failed to create directory: %v\n", mkdirErr)
823				continue
824			}
825	
826			agentSession := &agent.AgentSession{
827				SessionID:  sessionID,
828				AgentName:  sessionAgent.Name(),
829				RepoPath:   repoRoot,
830				SessionRef: sessionFile,
831				NativeData: content.Transcript,
832			}
833			if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
834				if totalSessions > 1 {
835					fmt.Fprintf(errW, "    Warning: failed to write session: %v\n", writeErr)
836					continue
837				}
838				return nil, fmt.Errorf("failed to write session: %w", writeErr)
839			}
840	
841			// Hand any agent-contributed extras (e.g., Cursor chat archives) back
842			// to the agent for restoration to native storage. Best-effort.
843			runCheckpointRestorer(ctx, errW, sessionAgent, sessionID, content.ExtraFiles)
844	
845			restored = append(restored, RestoredSession{
846				SessionID: sessionID,
847				Agent:     sessionAgent.Type(),
848				Prompt:    promptPreview,
849				CreatedAt: content.Metadata.CreatedAt,
850			})
851		}
852	
853		return restored, nil
854	}
855	
856	// ResolveAgentForRewind resolves the agent from checkpoint metadata.
857	func ResolveAgentForRewind(agentType types.AgentType) (agent.Agent, error) {
858		ag, err := agent.GetByAgentType(agentType)
859		if err != nil {
860			return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
861		}
862		return ag, nil
863	}
864	
865	// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
866	// Returns an empty string if the prompt cannot be read.
867	func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
868		// Get the commit and its tree
869		commit, err := repo.CommitObject(commitHash)
870		if err != nil {
871			return ""
872		}
873	
874		tree, err := commit.Tree()
875		if err != nil {
876			return ""
877		}
878	
879		// Look for prompt.txt in the metadata directory
880		promptPath := metadataDir + "/" + paths.PromptFileName
881		promptEntry, err := tree.File(promptPath)
882		if err != nil {
883			return ""
884		}
885	
886		content, err := promptEntry.Contents()
887		if err != nil {
888			return ""
889		}
890	
891		return ExtractFirstPrompt(content)
892	}
893	
894	// SessionRestoreStatus represents the status of a session being restored.
895	type SessionRestoreStatus int
896	
897	const (
898		StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
899		StatusUnchanged                                   // Local and checkpoint are the same
900		StatusCheckpointNewer                             // Checkpoint has newer entries
901		StatusLocalNewer                                  // Local has newer entries (conflict)
902	)
903	
904	// SessionRestoreInfo contains information about a session being restored.
905	type SessionRestoreInfo struct {
906		SessionID      string
907		Prompt         string               // First prompt preview for display
908		Status         SessionRestoreStatus // Status of this session
909		LocalTime      time.Time
910		CheckpointTime time.Time
911	}
912	
913	// classifySessionsForRestore checks all sessions in a checkpoint and returns info
914	// about each session, including whether local logs have newer timestamps.
915	// repoRoot is used to compute per-session agent directories.
916	// Sessions without agent metadata are skipped (cannot determine target directory).
917	func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store committedReader, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
918		var sessions []SessionRestoreInfo
919	
920		totalSessions := len(summary.Sessions)
921		// Check all sessions (0-based indexing)
922		for i := range totalSessions {
923			content, err := store.ReadSessionContent(ctx, checkpointID, i)
924			if err != nil || content == nil || len(content.Transcript) == 0 {
925				continue
926			}
927	
928			sessionID := content.Metadata.SessionID
929			if sessionID == "" || content.Metadata.Agent == "" {
930				continue
931			}
932	
933			sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
934			if agErr != nil {
935				continue
936			}
937	
938			// Compute transcript path from current repo location for cross-machine portability.
939			sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
940			if dirErr != nil {
941				continue
942			}
943			localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
944	
945			localTime := paths.GetLastTimestampFromFile(localPath)
946			checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
947			status := ClassifyTimestamps(localTime, checkpointTime)
948	
949			sessions = append(sessions, SessionRestoreInfo{
950				SessionID:      sessionID,
951				Prompt:         ExtractFirstPrompt(content.Prompts),
952				Status:         status,
953				LocalTime:      localTime,
954				CheckpointTime: checkpointTime,
955			})
956		}
957	
958		return sessions
959	}
960	
961	// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
962	func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
963		// Local file doesn't exist (no timestamp found)
964		if localTime.IsZero() {
965			return StatusNew
966		}
967	
968		// Can't determine checkpoint time - treat as new/safe
969		if checkpointTime.IsZero() {
970			return StatusNew
971		}
972	
973		// Compare timestamps
974		if localTime.After(checkpointTime) {
975			return StatusLocalNewer
976		}
977		if checkpointTime.After(localTime) {
978			return StatusCheckpointNewer
979		}
980		return StatusUnchanged
981	}
982	
983	// StatusToText returns a human-readable status string.
984	func StatusToText(status SessionRestoreStatus) string {
985		switch status {
986		case StatusNew:
987			return "(new)"
988		case StatusUnchanged:
989			return "(unchanged)"
990		case StatusCheckpointNewer:
991			return "(checkpoint is newer)"
992		case StatusLocalNewer:
993			return "(local is newer)" // shouldn't appear in non-conflict list
994		default:
995			return ""
996		}
997	}
998	
999	// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
1000	// session logs that have newer timestamps than the checkpoint versions.
1001	func PromptOverwriteNewerLogs(errW io.Writer, sessions []SessionRestoreInfo) (bool, error) {
1002		if !interactive.CanPromptInteractively() {
1003			return false, errors.New("cannot prompt to overwrite local session logs in non-interactive mode; rerun with --force to overwrite or use a TTY to confirm")
1004		}
1005	
1006		// Separate conflicting and non-conflicting sessions
1007		var conflicting, nonConflicting []SessionRestoreInfo
1008		for _, s := range sessions {
1009			if s.Status == StatusLocalNewer {
1010				conflicting = append(conflicting, s)
1011			} else {
1012				nonConflicting = append(nonConflicting, s)
1013			}
1014		}
1015	
1016		fmt.Fprintf(errW, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
1017		for _, info := range conflicting {
1018			// Show prompt if available, otherwise fall back to session ID
1019			if info.Prompt != "" {
1020				fmt.Fprintf(errW, "  \"%s\"\n", info.Prompt)
1021			} else {
1022				fmt.Fprintf(errW, "  Session: %s\n", info.SessionID)
1023			}
1024			fmt.Fprintf(errW, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
1025			fmt.Fprintf(errW, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
1026		}
1027	
1028		// Show non-conflicting sessions with their status
1029		if len(nonConflicting) > 0 {
1030			fmt.Fprintf(errW, "\nThese other session(s) will also be restored:\n")
1031			for _, info := range nonConflicting {
1032				statusText := StatusToText(info.Status)
1033				if info.Prompt != "" {
1034					fmt.Fprintf(errW, "  \"%s\" %s\n", info.Prompt, statusText)
1035				} else {
1036					fmt.Fprintf(errW, "  Session: %s %s\n", info.SessionID, statusText)
1037				}
1038			}
1039		}
1040	
1041		fmt.Fprintf(errW, "\nOverwriting will lose the newer local entries.\n\n")
1042	
1043		var confirmed bool
1044		form := huh.NewForm(
1045			huh.NewGroup(
1046				huh.NewConfirm().
1047					Title("Overwrite local session logs with checkpoint versions?").
1048					Value(&confirmed),
1049			),
1050		)
1051		if isAccessibleMode() {
1052			form = form.WithAccessible(true)
1053		}
1054	
1055		if err := form.Run(); err != nil {
1056			if errors.Is(err, huh.ErrUserAborted) {
1057				return false, nil
1058			}
1059			return false, fmt.Errorf("failed to get confirmation: %w", err)
1060		}
1061	
1062		return confirmed, nil
1063	}
1064

