// extractSessionDataFromLiveTranscript extracts session data directly from the live transcript file.
// This is used for mid-session commits where no shadow branch exists yet.
func (s *ManualCommitStrategy) extractSessionDataFromLiveTranscript(ctx context.Context, state *SessionState) (*ExtractedSessionData, error) {
	data := &ExtractedSessionData{}

	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe

	// Resolve the transcript path (handles agents that relocate mid-session).
	transcriptPath, resolveErr := resolveTranscriptPath(state)
	if resolveErr != nil {
		return nil, resolveErr
	}

	liveData, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
	if err != nil {
		return nil, fmt.Errorf("failed to read live transcript: %w", err)
	}

	if len(liveData) == 0 {
		return nil, errors.New("live transcript is empty")
	}

	fullTranscript := string(liveData)
	data.Transcript = liveData
	data.FullTranscriptLines = countTranscriptItems(state.AgentType, fullTranscript)
	data.Prompts = readPromptsFromFilesystem(ctx, state.SessionID)

	// Resolve files touched: prefers hook-populated state, falls back to transcript extraction
	data.FilesTouched = s.resolveFilesTouched(ctx, state)

	// Calculate token usage from the extracted transcript portion
	if len(data.Transcript) > 0 {
		data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, state.CheckpointTranscriptStart, "")
	}

	return data, nil
}

// refreshLiveExtras replaces stale shadow-branch copies of agent-contributed
// files with a fresh snapshot. On a mid-turn commit the shadow branch still
// carries the prior TurnEnd's archive (or none at all), so the committed
// checkpoint would otherwise miss the current turn's state. Queries every
// registered CheckpointContributor — not just state.AgentType — because
// session_id can be shared when multiple agents' hooks are installed in the
// same repo (cursor + claude-code both fire session-start on the same id, the
// later one wins on state.AgentType even if the other agent is doing the
// actual work).
func refreshLiveExtras(ctx context.Context, state *SessionState, sessionData *ExtractedSessionData) {
	live, err := contributeLiveExtras(ctx, state.SessionID)
	if err != nil {
		logging.Warn(logging.WithComponent(ctx, "checkpoint"), "agent live extras refresh failed",
			slog.String("session_id", state.SessionID),
			slog.String("agent_type", string(state.AgentType)),
			slog.String("error", err.Error()),
		)
		return
	}
	if len(live) == 0 {
		return
	}
	if sessionData.ExtraFiles == nil {
		sessionData.ExtraFiles = make(map[string][]byte, len(live))
	}
	maps.Copy(sessionData.ExtraFiles, live)
}

// contributeLiveExtras invokes every registered CheckpointContributor to refresh
// its archive files in the session metadata dir, then reads those files back
// into a map suitable for ExtraFiles. We iterate all contributors rather than
// just state.AgentType because multiple agents can share a session_id (for
// example when a repo enables both cursor and claude-code hooks, claude-code's
// session-start can overwrite agent_type in state even though cursor-agent is
// the one actually writing to ~/.cursor/chats/<id>/store.db). Contributors
// that have no data for this session are expected to return wrapped
// os.ErrNotExist, which we treat as a silent no-op.
func contributeLiveExtras(ctx context.Context, sessionID string) (map[string][]byte, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return map[string][]byte{}, fmt.Errorf("worktree root: %w", err)
	}
	metadataDirAbs := filepath.Join(worktreeRoot, paths.SessionMetadataDirFromSessionID(sessionID))
	if mkErr := os.MkdirAll(metadataDirAbs, 0o750); mkErr != nil {
		return map[string][]byte{}, fmt.Errorf("ensure metadata dir: %w", mkErr)
	}

	for _, name := range agent.List() {
		ag, getErr := agent.Get(name)
		if getErr != nil {
			continue
		}
		contributor, ok := ag.(agent.CheckpointContributor)
		if !ok {
			continue
		}
		if err := contributor.ContributeCheckpointFiles(ctx, sessionID, metadataDirAbs); err != nil && !errors.Is(err, os.ErrNotExist) {
			logging.Debug(logging.WithComponent(ctx, "checkpoint"), "live extras contributor failed",
				slog.String("session_id", sessionID),
				slog.String("agent", string(name)),
				slog.String("error", err.Error()),
			)
		}
	}

	entries, err := os.ReadDir(metadataDirAbs)
	if err != nil {
		return map[string][]byte{}, fmt.Errorf("read metadata dir: %w", err)
	}
	extras := map[string][]byte{}
	for _, e := range entries {
		if e.IsDir() || standardMetadataFiles[e.Name()] {
			continue
		}
		content, readErr := os.ReadFile(filepath.Join(metadataDirAbs, e.Name())) //nolint:gosec // our own metadata dir
		if readErr != nil {
			return map[string][]byte{}, fmt.Errorf("read %s: %w", e.Name(), readErr)
		}
		extras[e.Name()] = content
	}
	return extras, nil
}

// standardMetadataFiles is the set of files written by the framework during SaveStep.
// Any other file in the metadata directory is considered an agent-contributed extra file.
var standardMetadataFiles = map[string]bool{
	paths.TranscriptFileName:        true,
	paths.TranscriptFileNameLegacy:  true,
	paths.CompactTranscriptFileName: true,
	paths.V2RawTranscriptFileName:   true,
	paths.PromptFileName:            true,
	paths.MetadataFileName:          true,
	paths.ContentHashFileName:       true,
}

// extractExtraFilesFromTree walks the shadow branch tree under metadataDir and
// returns any files that are not part of the standard metadata set. These are
// agent-contributed files (e.g., .cursor-chat.json archives).
func extractExtraFilesFromTree(tree *object.Tree, metadataDir string) map[string][]byte {
	prefix := metadataDir + "/"
	extras := make(map[string][]byte)

	_ = tree.Files().ForEach(func(f *object.File) error { //nolint:errcheck // best-effort: extra files are optional
		if !strings.HasPrefix(f.Name, prefix) {
			return nil
		}
		relPath := strings.TrimPrefix(f.Name, prefix)
		// Skip subdirectories (tasks/) and standard files
		if strings.Contains(relPath, "/") {
			return nil
		}
		if standardMetadataFiles[relPath] {
			return nil
		}
		// Read via Reader, not Contents(): Contents() returns string, which loses
		// raw bytes for any non-UTF8 file. ExtraFiles is typed as []byte so we
		// stream the blob through io.ReadAll to preserve exact bytes.
		reader, err := f.Reader()
		if err != nil {
			return nil //nolint:nilerr // best-effort: skip files we can't read
		}
		content, err := io.ReadAll(reader)
		_ = reader.Close()
		if err != nil {
			return nil //nolint:nilerr // best-effort: skip files we can't read
		}
		extras[relPath] = content
		return nil
	})

	if len(extras) == 0 {
		return nil
	}
	return extras
}

// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
// For Claude Code and JSONL-based agents, this counts lines.
// For Gemini CLI, OpenCode, and JSON-based agents, this counts messages.
// Returns 0 if the content is empty or malformed.
func countTranscriptItems(agentType types.AgentType, content string) int {
	if content == "" {
		return 0
	}

	// OpenCode uses export JSON format with {"info": {...}, "messages": [...]}
	if agentType == agent.AgentTypeOpenCode {

		Transcript:                  redactedTranscript,
