1	package cursor
2	
3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"database/sql"
8		"encoding/base64"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"os"
13		"path/filepath"
14		"reflect"
15		"testing"
16	)
17	
18	const (
19		testAgentID   = "11111111-2222-3333-4444-555555555555"
20		testWorkspace = "abc123hash"
21	)
22	
23	// seedStoreDB creates a real cursor-format SQLite store.db under
24	// $HOME/.cursor/chats/<workspace>/<testAgentID>/ with the given meta + blobs.
25	// Returns the path to store.db so callers can chmod it for read-only tests.
26	func seedStoreDB(t *testing.T, home string, metaValue []byte, blobs map[string][]byte) string {
27		t.Helper()
28		dbDir := filepath.Join(home, ".cursor", "chats", testWorkspace, testAgentID)
29		if err := os.MkdirAll(dbDir, 0o755); err != nil {
30			t.Fatalf("mkdir chats: %v", err)
31		}
32		dbPath := filepath.Join(dbDir, "store.db")
33	
34		db, err := sql.Open("sqlite", dbPath)
35		if err != nil {
36			t.Fatalf("open seed db: %v", err)
37		}
38		t.Cleanup(func() { _ = db.Close() })
39	
40		if _, err := db.ExecContext(context.Background(),`
41			CREATE TABLE meta  (key TEXT PRIMARY KEY, value TEXT);
42			CREATE TABLE blobs (id  TEXT PRIMARY KEY, data BLOB);
43		`); err != nil {
44			t.Fatalf("create tables: %v", err)
45		}
46		if metaValue != nil {
47			// Cursor stores meta.value as hex-ASCII of the JSON bytes.
48			if _, err := db.ExecContext(context.Background(),"INSERT INTO meta(key, value) VALUES('0', ?)", hex.EncodeToString(metaValue)); err != nil {
49				t.Fatalf("insert meta: %v", err)
50			}
51		}
52		for id, data := range blobs {
53			if _, err := db.ExecContext(context.Background(),"INSERT INTO blobs(id, data) VALUES(?, ?)", id, data); err != nil {
54				t.Fatalf("insert blob %s: %v", id, err)
55			}
56		}
57		if err := db.Close(); err != nil {
58			t.Fatalf("close seed db: %v", err)
59		}
60		return dbPath
61	}
62	
63	// parseArchiveLines reads the JSONL export and splits it into meta + blob rows.
64	func parseArchiveLines(t *testing.T, data []byte) (metas []jsonlLine, blobs []jsonlLine) {
65		t.Helper()
66		scanner := bufio.NewScanner(bytes.NewReader(data))
67		scanner.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
68		for scanner.Scan() {
69			var l jsonlLine
70			if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
71				t.Fatalf("unmarshal line %q: %v", scanner.Text(), err)
72			}
73			switch l.T {
74			case "meta":
75				metas = append(metas, l)
76			case "blob":
77				blobs = append(blobs, l)
78			default:
79				t.Fatalf("unexpected row type %q", l.T)
80			}
81		}
82		if err := scanner.Err(); err != nil {
83			t.Fatalf("scan: %v", err)
84		}
85		return metas, blobs
86	}
