206	func TestExportChatArchive_BlobsSortedByID(t *testing.T) {
207		// Deterministic ordering lets git pack dedup across checkpoints.
208		tmp := t.TempDir()
209		t.Setenv("HOME", tmp)
210	
211		blobBytes := map[string][]byte{
212			"ccc": []byte("c"),
213			"aaa": []byte("a"),
214			"bbb": []byte("b"),
