246	func TestExportChatArchive_ReadOnly_DoesNotMutateSource(t *testing.T) {
247		// Export copies DB + sidecars to a temp dir before opening, so the
248		// cursor-live files on disk must be byte-identical after export.
249		tmp := t.TempDir()
250		t.Setenv("HOME", tmp)
251	
252		dbPath := seedStoreDB(t, tmp, []byte(`{"k":"v"}`), map[string][]byte{"id": []byte("data")})
253	
254		before := statAll(t, dbPath)
255		if _, err := ExportChatArchive(context.Background(), testAgentID); err != nil {
256			t.Fatalf("ExportChatArchive: %v", err)
257		}
258		after := statAll(t, dbPath)
259	
260		for k, b := range before {
261			a := after[k]
262			if !b.ModTime().Equal(a.ModTime()) {
263				t.Errorf("%s modtime changed", k)
264			}
265			if b.Size() != a.Size() {
266				t.Errorf("%s size changed: %d -> %d", k, b.Size(), a.Size())
267			}
268		}
