271	func statAll(t *testing.T, dbPath string) map[string]os.FileInfo {
272		t.Helper()
273		out := map[string]os.FileInfo{}
274		for _, suffix := range []string{"", "-wal", "-shm"} {
275			info, err := os.Stat(dbPath + suffix)
276			if err != nil {
277				continue
278			}
279			out["store.db"+suffix] = info
280		}
281		return out
282	}
