17	// TestCreateRedactedBlob_OpaqueArchive_NotRedacted verifies that files
18	// recognized as opaque agent archives bypass the redaction pass. Covers both
19	// the legacy v2 shape (.cursor-chat.json wrapping a base64 SQLite blob) and
20	// the current v3 shape (cursor-chat.jsonl, per-row JSONL with base64 blob
21	// payloads). Without the bypass, random byte sequences inside the base64
22	// payload can match a secret pattern and get replaced with "REDACTED",
23	// corrupting the archive so its consumer fails to base64-decode the blob.
24	func TestCreateRedactedBlob_OpaqueArchive_NotRedacted(t *testing.T) {
25		t.Parallel()
26	
27		// A "secret-looking" token that the redactor would otherwise hit.
28		secretLike := "AKIAIOSFODNN7EXAMPLE"
29		cases := []struct {
30			name     string
31			filename string
32			treePath string
33			content  []byte
34		}{
35			{
36				name:     "v2_single_json",
37				filename: "session.cursor-chat.json",
38				treePath: "metadata/session.cursor-chat.json",
39				content:  []byte(`{"format":"cursor-chat-export","version":2,"db_bytes":"` + secretLike + `"}`),
40			},
41			{
42				name:     "v3_jsonl",
43				filename: "cursor-chat.jsonl",
44				treePath: "metadata/session/cursor-chat.jsonl",
45				content:  []byte(`{"t":"blob","id":"xx","data":"` + secretLike + `"}` + "\n"),
46			},
47		}
48		for _, tc := range cases {
49			t.Run(tc.name, func(t *testing.T) {
50				t.Parallel()
51				tempDir := t.TempDir()
52				repo, err := git.PlainInit(tempDir, false)
53				if err != nil {
54					t.Fatalf("git init: %v", err)
55				}
56				filePath := filepath.Join(tempDir, tc.filename)
57				if err := os.WriteFile(filePath, tc.content, 0o600); err != nil {
58					t.Fatal(err)
59				}
60				hash, _, err := createRedactedBlobFromFile(repo, filePath, tc.treePath)
61				if err != nil {
62					t.Fatalf("createRedactedBlobFromFile: %v", err)
63				}
64				blob, err := repo.BlobObject(hash)
65				if err != nil {
66					t.Fatalf("BlobObject: %v", err)
67				}
68				reader, err := blob.Reader()
69				if err != nil {
70					t.Fatalf("blob reader: %v", err)
71				}
72				defer reader.Close()
73				got := make([]byte, blob.Size)
74				if _, err := reader.Read(got); err != nil {
75					t.Fatalf("read blob: %v", err)
76				}
77				if string(got) != string(tc.content) {
78					t.Errorf("blob contents mutated by redaction:\ngot:  %s\nwant: %s", got, tc.content)
79				}
80			})
81		}
82	}
83	
84	// TestWriteCommitted_ReadSessionContent_RoundtripsExtraFiles verifies that
85	// agent-contributed extra files survive the checkpoint write/read roundtrip
86	// on the metadata branch. This is the commit→resume path that lets an agent's
87	// CheckpointRestorer recover its native data (e.g., Cursor's store.db).
88	func TestWriteCommitted_ReadSessionContent_RoundtripsExtraFiles(t *testing.T) {
89		t.Parallel()
90	
91		tempDir := t.TempDir()
92		repo, err := git.PlainInit(tempDir, false)
93		if err != nil {
94			t.Fatalf("git init: %v", err)
95		}
96		worktree, err := repo.Worktree()
97		if err != nil {
98			t.Fatalf("worktree: %v", err)
99		}
100		if err := os.WriteFile(filepath.Join(tempDir, "README.md"), []byte("x"), 0o644); err != nil {
101			t.Fatal(err)
102		}
103		if _, err := worktree.Add("README.md"); err != nil {
104			t.Fatal(err)
105		}
106		if _, err := worktree.Commit("init", &git.CommitOptions{
107			Author: &object.Signature{Name: "t", Email: "t@t"},
108		}); err != nil {
109			t.Fatal(err)
110		}
111	
112		store := NewGitStore(repo)
113		checkpointID := id.MustCheckpointID("abc123def456")
114	
115		sessionID := "2026-04-22-zzz"
116		extras := map[string][]byte{
117			sessionID + ".cursor-chat.json": []byte(`{"format":"cursor-chat-export","version":2}`),
118		}
119	
120		if err := store.WriteCommitted(context.Background(), WriteCommittedOptions{
121			CheckpointID: checkpointID,
122			SessionID:    sessionID,
123			Strategy:     "manual-commit",
124			Agent:        types.AgentType("Cursor"),
125			Transcript:   redact.AlreadyRedacted([]byte(`{"role":"user","content":"hi"}` + "\n")),
126			AuthorName:   "t",
127			AuthorEmail:  "t@t",
128			ExtraFiles:   extras,
129		}); err != nil {
130			t.Fatalf("WriteCommitted: %v", err)
131		}
132	
133		content, err := store.ReadSessionContent(context.Background(), checkpointID, 0)
134		if err != nil {
135			t.Fatalf("ReadSessionContent: %v", err)
136		}
137		if content.ExtraFiles == nil {
138			t.Fatalf("expected ExtraFiles to be populated, got nil")
139		}
140		got, ok := content.ExtraFiles[sessionID+".cursor-chat.json"]
141		if !ok {
142			t.Fatalf("expected key %q in ExtraFiles, got %v", sessionID+".cursor-chat.json", content.ExtraFiles)
143		}
144		if string(got) != string(extras[sessionID+".cursor-chat.json"]) {
145			t.Errorf("ExtraFiles bytes mismatch")
146		}
147	}
