	// Cursor itself resolves symlinks when computing the workspace hash/slug
	// (e.g. on macOS /var/folders → /private/var/folders). Match that so test
	// assertions align with what RestoreCheckpointFiles wrote.
	resolvedDir, err := filepath.EvalSymlinks(dir)
	if err != nil {
		t.Fatalf("EvalSymlinks(%s): %v", dir, err)
	}

	// ~/.cursor/chats: assert store.db + wal written at the expected md5-hashed dir.
	wantHash := cursor.WorkspaceHash(resolvedDir)
	dbPath := filepath.Join(home, ".cursor", "chats", wantHash, sessionID, "store.db")
	got, err := os.ReadFile(dbPath)
	if err != nil {
		t.Fatalf("expected store.db at %s: %v", dbPath, err)
	}
	if string(got) != string(originalDB) {
		t.Errorf("store.db bytes mismatch: got %q, want %q", got, originalDB)
	}
	gotWAL, err := os.ReadFile(dbPath + "-wal")
	if err != nil {
		t.Fatalf("expected store.db-wal at %s: %v", dbPath+"-wal", err)
	}
	if string(gotWAL) != string(originalWAL) {
		t.Errorf("wal bytes mismatch")
	}

	// ~/.cursor/projects: assert transcript JSONL written at the slug/nested path.
	wantSlug := cursor.WorkspaceSlug(resolvedDir)
	txPath := filepath.Join(home, ".cursor", "projects", wantSlug, "agent-transcripts", sessionID, sessionID+".jsonl")
	txBytes, err := os.ReadFile(txPath)
	if err != nil {
		t.Fatalf("expected transcript at %s: %v", txPath, err)
	}
	if !strings.Contains(string(txBytes), `"role":"user"`) {
		t.Errorf("transcript content mismatch: got %q", txBytes)
	}
}

// TestRewind_RestoresCursorChatArchiveV3 seeds a checkpoint with a v3 JSONL
// archive (cursor-chat.jsonl) and asserts Rewind rebuilds store.db with the
// same meta + blobs rows the source dumped.
func TestRewind_RestoresCursorChatArchiveV3(t *testing.T) {
	// Cannot t.Parallel: t.Chdir + t.Setenv mutate process globals.
	dir := t.TempDir()
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	repo, err := git.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("git init: %v", err)
	}
	worktree, err := repo.Worktree()
	if err != nil {
		t.Fatalf("worktree: %v", err)
	}
	author := &object.Signature{Name: "t", Email: "t@t", When: time.Now()}

	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("x\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := worktree.Add("README.md"); err != nil {
		t.Fatal(err)
	}
	initial, err := worktree.Commit("init", &git.CommitOptions{Author: author})
	if err != nil {
		t.Fatalf("initial commit: %v", err)
	}

	// Seed v3 archive. Use distinctive bytes so we can prove roundtrip.
	sessionID := "2026-04-24-v3session"
	metaJSON := []byte(`{"agentId":"` + sessionID + `","latestRootBlobId":"root","name":"V3"}`)
	blobContents := map[string][]byte{
		"blob-a": []byte(`{"role":"user","content":"first"}`),
		"blob-b": []byte(`{"role":"assistant","content":"second"}`),
	}

	var jsonlBuf strings.Builder
	metaLine, err := json.Marshal(map[string]any{
		"t": "meta",
		"k": "0",
		"v": json.RawMessage(metaJSON),
	})
	if err != nil {
		t.Fatalf("marshal meta line: %v", err)
	}
	jsonlBuf.Write(metaLine)
	jsonlBuf.WriteByte('\n')
	for _, id := range []string{"blob-a", "blob-b"} {
		line, err := json.Marshal(map[string]any{
			"t":    "blob",
			"id":   id,
			"data": base64.StdEncoding.EncodeToString(blobContents[id]),
		})
		if err != nil {
			t.Fatalf("marshal blob line: %v", err)
		}
		jsonlBuf.Write(line)
		jsonlBuf.WriteByte('\n')
	}

	metadataDir := filepath.Join(dir, entireDir, "metadata", sessionID)
	if err := os.MkdirAll(metadataDir, 0o755); err != nil {
		t.Fatal(err)
	}
	archiveRel := filepath.Join(entireDir, "metadata", sessionID, "cursor-chat.jsonl")
	if err := os.WriteFile(filepath.Join(dir, archiveRel), []byte(jsonlBuf.String()), 0o600); err != nil {
		t.Fatal(err)
	}

	if _, err := worktree.Add(archiveRel); err != nil {
		t.Fatalf("add archive: %v", err)
	}
	checkpointHash, err := worktree.Commit(
		"Checkpoint\n\nEntire-Session: "+sessionID,
		&git.CommitOptions{Author: author},
	)
	if err != nil {
		t.Fatalf("checkpoint commit: %v", err)
	}

	s := NewManualCommitStrategy()
	state := &SessionState{
		SessionID:    sessionID,
		BaseCommit:   initial.String(),
		StartedAt:    time.Now(),
		AgentType:    types.AgentType("Cursor"),
		StepCount:    1,
		WorktreePath: dir,
	}
	if err := s.saveSessionState(context.Background(), state); err != nil {
		t.Fatalf("save state: %v", err)
	}

	if err := worktree.Reset(&git.ResetOptions{Commit: initial, Mode: git.HardReset}); err != nil {
		t.Fatalf("reset: %v", err)
	}

	if err := s.Rewind(context.Background(), io.Discard, io.Discard, RewindPoint{
		ID:      checkpointHash.String(),
		Message: "Checkpoint",
		Date:    time.Now(),
	}); err != nil {
		t.Fatalf("Rewind: %v", err)
	}

	resolvedDir, err := filepath.EvalSymlinks(dir)
	if err != nil {
		t.Fatalf("EvalSymlinks: %v", err)
	}
	wantHash := cursor.WorkspaceHash(resolvedDir)
	dbPath := filepath.Join(home, ".cursor", "chats", wantHash, sessionID, "store.db")

	// Open the reconstructed DB and assert both tables match the source.
	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		t.Fatalf("open restored db: %v", err)
	}
	defer db.Close()

	var metaHex string
	if err := db.QueryRowContext(context.Background(), "SELECT value FROM meta WHERE key = '0'").Scan(&metaHex); err != nil {
		t.Fatalf("select meta: %v", err)
	}
	metaBytes, err := hex.DecodeString(metaHex)
	if err != nil {
		t.Fatalf("hex decode meta: %v", err)
	}
	if !strings.Contains(string(metaBytes), `"name":"V3"`) {
		t.Errorf("meta roundtrip: got %s, want value containing \"name\":\"V3\"", metaBytes)
	}

	rows, err := db.QueryContext(context.Background(), "SELECT id, data FROM blobs ORDER BY id")
	if err != nil {
		t.Fatalf("select blobs: %v", err)
	}
	defer rows.Close()
	got := map[string][]byte{}
	for rows.Next() {
		var id string
		var data []byte
		if err := rows.Scan(&id, &data); err != nil {
			t.Fatalf("scan blob: %v", err)
		}
		got[id] = data
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("blobs iter: %v", err)
	}
	for id, want := range blobContents {
		have, ok := got[id]
		if !ok {
			t.Errorf("blob %q missing from restored db", id)
			continue
		}
		if string(have) != string(want) {
			t.Errorf("blob %q roundtrip mismatch: got %q want %q", id, have, want)
		}
	}
	if len(got) != len(blobContents) {
		t.Errorf("restored blob count = %d, want %d", len(got), len(blobContents))
	}
}

package cli

import (
	"context"
	"fmt"
	"net"
	"os"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/go-git/go-git/v6/config"
	format "github.com/go-git/go-git/v6/plumbing/format/config"
	"github.com/go-git/go-git/v6/x/plugin"
	"github.com/go-git/x/plugin/objectsigner/auto"
	"golang.org/x/crypto/ssh/agent"
)

var registerObjectSignerOnce sync.Once
var objectSignerLoader = loadObjectSigner

func RegisterObjectSigner() {
	registerObjectSignerOnce.Do(func() {
		signer, ok := objectSignerLoader()
		if !ok {
			return
		}

		//nolint:errcheck,gosec // best-effort; if registration fails, commits are left unsigned
		plugin.Register(plugin.ObjectSigner(), func() plugin.Signer {
			return signer
		})
	})
}

func loadObjectSigner() (plugin.Signer, bool) {
	cfgSource, err := plugin.Get(plugin.ConfigLoader())
	if err != nil {
		// No config loader registered; signing not possible.
		return nil, false
	}

	sysCfg := loadScopedConfig(cfgSource, config.SystemScope)
	globalCfg := loadScopedConfig(cfgSource, config.GlobalScope)

	// Merge system then global so that global settings take precedence.
	merged := config.Merge(sysCfg, globalCfg)

	if !merged.Commit.GpgSign.IsTrue() {
		return nil, false
	}

	// When a custom gpg.ssh.program is configured (e.g. 1Password's
	// op-ssh-sign), signing happens via an external binary that go-git
	// cannot invoke. Skip native signing silently — checkpoint commits
	// will be unsigned, which is acceptable since signing is best-effort.
	// The default program is "ssh-keygen", which works with go-git's
	// native SSH agent signing and does not need to be skipped.
	if auto.Format(merged.GPG.Format) == auto.FormatSSH && hasCustomSSHSignProgram(merged.Raw) {
		logging.Debug(context.Background(), "skipping native SSH commit signing: custom gpg.ssh.program is configured")
		return nil, false
	}

	signer, err := auto.FromConfig(auto.Config{
		SigningKey: merged.User.SigningKey,
		Format:     auto.Format(merged.GPG.Format),
		SSHAgent:   connectSSHAgent(),
	})
	if err != nil {
		logging.Debug(context.Background(), "failed to create object signer", "error", err.Error())
		return nil, false
	}

	return signer, true
}

// connectSSHAgent connects to the SSH agent via SSH_AUTH_SOCK.
// Returns nil if the agent is unavailable.
func connectSSHAgent() agent.Agent {
	sock := os.Getenv("SSH_AUTH_SOCK")
	if sock == "" {
		return nil
	}

	var d net.Dialer
	conn, err := d.DialContext(context.Background(), "unix", sock)
	if err != nil {
		return nil
	}

	return agent.NewClient(conn)
}

var scopeName = map[config.Scope]string{
	config.GlobalScope: "global",
	config.SystemScope: "system",
}

// hasCustomSSHSignProgram checks whether gpg.ssh.program is set to a
// non-default value in the raw config. The git default is "ssh-keygen",
// which works with go-git's native SSH agent signing. Custom programs
// (e.g. 1Password's op-ssh-sign) use a separate signing mechanism that
// go-git cannot invoke.
// go-git's Config struct does not expose this field, so we read it directly.
func hasCustomSSHSignProgram(raw *format.Config) bool {
	if raw == nil {
		return false
	}

	program := raw.Section("gpg").Subsection("ssh").Option("program")

	return program != "" && program != "ssh-keygen"
}

func loadScopedConfig(source plugin.ConfigSource, scope config.Scope) *config.Config {
	name := scopeName[scope]

	storer, err := source.Load(scope)
	if err != nil {
		fmt.Fprintf(os.Stderr, "warning: failed to load %s git config: %v\n", name, err)
		return config.NewConfig()
	}

	cfg, err := storer.Config()
	if err != nil {
		fmt.Fprintf(os.Stderr, "warning: failed to parse %s git config: %v\n", name, err)
		return config.NewConfig()
	}

	return cfg
}

package checkpoint

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"os/exec"

	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/storer"
)

// BlobFetchFunc fetches missing blob objects by hash from a remote.
type BlobFetchFunc func(ctx context.Context, hashes []plumbing.Hash) error

// FetchingTree wraps a git tree to automatically fetch missing blobs on demand.
// After a treeless fetch (--filter=blob:none), tree objects are available locally
// but blob objects are not. Each File() call checks whether the target blob
// exists locally and fetches it from the remote if missing, using FindEntry
// to locate the blob hash without resolving the blob itself.
//
// Because go-git's ObjectStorage caches the packfile index and never refreshes
// it, blobs fetched by external git commands (e.g. git fetch-pack) may not be
// visible to go-git's storer. As a fallback, File() reads the blob via
// "git cat-file" which always sees the current on-disk object store.
//
// For best performance, call PreFetch before reading files. PreFetch walks
// the tree, identifies locally-missing blobs, and batch-fetches them in a
// single network round-trip instead of one fetch per File() miss.
type FetchingTree struct {
	inner  *object.Tree
	ctx    context.Context
	storer storer.EncodedObjectStorer
	fetch  BlobFetchFunc
}

// InnerTree exposes the underlying *object.Tree for callers that need raw
// iteration (e.g., Files().ForEach). Blob fetching is bypassed when reading
// via the returned tree — use File() for lazy-fetch semantics.
func (t *FetchingTree) InnerTree() *object.Tree {
	return t.inner
}

// NewFetchingTree wraps a git tree with on-demand blob fetching.
// The storer is used to check if blobs exist locally, and fetch is called
// to download any that are missing. If fetch is nil, File() behaves
// identically to the underlying tree.
func NewFetchingTree(ctx context.Context, tree *object.Tree, s storer.EncodedObjectStorer, fetch BlobFetchFunc) *FetchingTree {
	return &FetchingTree{
		inner:  tree,
		ctx:    ctx,
		storer: s,
		fetch:  fetch,
	}
}

// File returns the file at the given path. If the blob is not available
// locally (e.g. after a treeless fetch), it is fetched on demand. If go-git's
// storer still can't see the blob after fetching (due to cached packfile index),
// the blob is read via "git cat-file" and an in-memory File is returned.
func (t *FetchingTree) File(path string) (*object.File, error) {
	// Fast path: blob already available in go-git's storer.
	file, err := t.inner.File(path)
	if err == nil {
		return file, nil
	}

	if t.fetch == nil {
		return nil, err //nolint:wrapcheck // pass-through wrapper
	}

	// Find the tree entry to get the blob hash without resolving the blob.
	// FindEntry only navigates tree objects (available after --filter=blob:none).
	entry, findErr := t.inner.FindEntry(path)
	if findErr != nil {
		logging.Debug(t.ctx, "FetchingTree.File: entry not found",
			slog.String("path", path),
			slog.String("error", findErr.Error()),
		)
		return nil, err //nolint:wrapcheck // return original File() error
	}

	logging.Debug(t.ctx, "FetchingTree.File: blob missing, fetching",
		slog.String("path", path),
		slog.String("hash", entry.Hash.String()[:12]),
	)

	// Fetch the blob from the remote.
	if fetchErr := t.fetch(t.ctx, []plumbing.Hash{entry.Hash}); fetchErr != nil {
		logging.Warn(t.ctx, "FetchingTree.File: blob fetch failed",
			slog.String("path", path),
			slog.String("hash", entry.Hash.String()[:12]),
			slog.String("error", fetchErr.Error()),
		)
		return nil, err //nolint:wrapcheck // return original File() error
	}

	// Try go-git again — works if blob was stored as a loose object.
	file, err = t.inner.File(path)
	if err == nil {
		return file, nil
	}

	// go-git's storer caches the packfile index and won't see new packs
	// created by external git commands. Fall back to "git cat-file" which
	// reads directly from the on-disk object store.
	logging.Debug(t.ctx, "FetchingTree.File: storer cache stale, reading via git cat-file",
		slog.String("path", path),
		slog.String("hash", entry.Hash.String()[:12]),
	)
	return t.readFileViaGit(path, entry)
}

// PreFetch walks the tree recursively, identifies blob entries that are missing
// from the local object store, and batch-fetches them in a single call to
// t.fetch. This avoids per-blob network round-trips during subsequent File()
// calls. It is safe to call even when all blobs are already local (no-op).
// Returns the number of blobs fetched.
func (t *FetchingTree) PreFetch() (int, error) {
	if t.fetch == nil || t.storer == nil {
		return 0, nil
	}

	missing := t.collectMissingBlobs(t.inner)
	if len(missing) == 0 {
		return 0, nil
	}

	logging.Debug(t.ctx, "FetchingTree.PreFetch: batch-fetching missing blobs",
		slog.Int("count", len(missing)),
	)

	if err := t.fetch(t.ctx, missing); err != nil {
		return 0, fmt.Errorf("prefetch %d blobs: %w", len(missing), err)
	}

	return len(missing), nil
}

// collectMissingBlobs recursively walks a tree and returns hashes of blob
// entries that are not present in the local object store.
func (t *FetchingTree) collectMissingBlobs(tree *object.Tree) []plumbing.Hash {
	var missing []plumbing.Hash
	for _, entry := range tree.Entries {
		if entry.Mode.IsFile() {
			if t.storer.HasEncodedObject(entry.Hash) != nil {
				missing = append(missing, entry.Hash)
			}
		} else {
			// Recurse into subtrees (tree objects are local after treeless fetch).
			subtree, err := tree.Tree(entry.Name)
			if err == nil {
				missing = append(missing, t.collectMissingBlobs(subtree)...)
			}
		}
	}
	return missing
}

// readFileViaGit reads a blob via "git cat-file -p <hash>" and returns an
// in-memory *object.File. This bypasses go-git's storer which may have a
// stale packfile index after external git commands fetched new objects.
func (t *FetchingTree) readFileViaGit(path string, entry *object.TreeEntry) (*object.File, error) {
	cmd := exec.CommandContext(t.ctx, "git", "cat-file", "-p", entry.Hash.String())
	content, cmdErr := cmd.Output()
	if cmdErr != nil {
		logging.Warn(t.ctx, "FetchingTree.readFileViaGit: cat-file failed",
			slog.String("path", path),
			slog.String("hash", entry.Hash.String()[:12]),
			slog.String("error", cmdErr.Error()),
		)
		return nil, fmt.Errorf("blob %s not readable after fetch: %w", entry.Hash.String()[:12], cmdErr)
	}

	// Create an in-memory encoded object to construct the File.
	memObj := &plumbing.MemoryObject{}
	memObj.SetType(plumbing.BlobObject)
	memObj.SetSize(int64(len(content)))
	w, wErr := memObj.Writer()
	if wErr != nil {
		return nil, fmt.Errorf("memory object writer: %w", wErr)
	}
	if _, wErr = w.Write(content); wErr != nil {
		return nil, fmt.Errorf("memory object write: %w", wErr)
	}
	if wErr = w.Close(); wErr != nil {
		return nil, fmt.Errorf("memory object close: %w", wErr)
	}

	blob := &object.Blob{}
	if dErr := blob.Decode(memObj); dErr != nil {
		return nil, fmt.Errorf("blob decode: %w", dErr)
	}

	logging.Debug(t.ctx, "FetchingTree.readFileViaGit: blob read successfully",
		slog.String("path", path),
		slog.String("hash", entry.Hash.String()[:12]),
		slog.Int64("size", int64(len(content))),
	)

	return object.NewFile(path, entry.Mode, blob), nil
}

// Tree returns the subtree at the given path, wrapped with the same fetching
// behavior.
func (t *FetchingTree) Tree(path string) (*FetchingTree, error) {
	subtree, err := t.inner.Tree(path)
	if err != nil {
		return nil, fmt.Errorf("tree %s: %w", path, err)
	}
	return &FetchingTree{
		inner:  subtree,
		ctx:    t.ctx,
		storer: t.storer,
		fetch:  t.fetch,
	}, nil
}

// RawEntries returns the direct tree entries (no blob reads needed).
func (t *FetchingTree) RawEntries() []object.TreeEntry {
	return t.inner.Entries
}

// Unwrap returns the underlying *object.Tree.
func (t *FetchingTree) Unwrap() *object.Tree {
	return t.inner
}

// Files returns a recursive file iterator from the underlying tree.
// Warning: after a treeless fetch, this iterator will fail when it tries
// to resolve blob objects. Use File() for on-demand blob fetching instead.
func (t *FetchingTree) Files() *object.FileIter {
	return t.inner.Files()
}

// FileReader provides read access to files within a git tree.
// Both *object.Tree and *FetchingTree implement this interface.
type FileReader interface {
	File(path string) (*object.File, error)
}

// FileOpener provides access to a file's content reader.
// *object.File implements this interface.
type FileOpener interface {
	Reader() (io.ReadCloser, error)
}

