280	// writeCommittedMain writes metadata entries to the /main ref.
281	// This includes session metadata and prompts — but NOT the raw transcript
282	// (raw_transcript) or content hash (raw_transcript_hash.txt), which go to /full/current.
283	// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
284	func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
285		refName := plumbing.ReferenceName(paths.V2MainRefName)
286		if err := s.ensureRef(ctx, refName); err != nil {
287			return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
288		}
289	
290		parentHash, rootTreeHash, err := s.GetRefState(refName)
291		if err != nil {
292			return 0, err
293		}
294	
295		basePath := opts.CheckpointID.Path() + "/"
296		checkpointPath := opts.CheckpointID.Path()
297	
298		// Read existing entries at this checkpoint's shard path
299		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
300		if err != nil {
301			return 0, err
302		}
303	
304		// Build main session entries (metadata, prompts — no transcript or content hash)
305		sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
306		if err != nil {
307			return 0, err
308		}
309	
310		// Splice entries into root tree
311		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
312		if err != nil {
313			return 0, err
314		}
315	
316		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
317		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
318			return 0, err
319		}
320		return sessionIndex, nil
321	}
