214	// BranchExists checks if a branch exists in the repository.
215	func BranchExists(t *testing.T, repoDir, branchName string) bool {
216		t.Helper()
217	
218		repo, err := git.PlainOpen(repoDir)
219		if err != nil {
220			t.Fatalf("failed to open git repo: %v", err)
221		}
222	
223		refs, err := repo.References()
224		if err != nil {
225			t.Fatalf("failed to get references: %v", err)
226		}
227	
228		found := false
229		//nolint:errcheck,gosec // ForEach callback doesn't return errors we need to handle
230		refs.ForEach(func(ref *plumbing.Reference) error {
231			if ref.Name().Short() == branchName {
232				found = true
233			}
234			return nil
235		})
